import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"ERB 文件结构","description":"","frontmatter":{},"headers":[],"relativePath":"reference/ERB_Structure.md","filePath":"reference/ERB_Structure.md"}`),a={name:`reference/ERB_Structure.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="erb-文件结构" tabindex="-1">ERB 文件结构 <a class="header-anchor" href="#erb-文件结构" aria-label="Permalink to “ERB 文件结构”">​</a></h1><p><code>ERB/</code> 文件夹存放游戏的脚本。Emuera 启动时会读取这里所有扩展名为 <code>.erb</code> 的文件，以及 <code>.erh</code> 头文件。</p><h2 id="文件与编码" tabindex="-1">文件与编码 <a class="header-anchor" href="#文件与编码" aria-label="Permalink to “文件与编码”">​</a></h2><ul><li>脚本文件扩展名为 <code>.erb</code>，头文件为 <code>.erh</code>；</li><li>编码通常为 <strong>Shift-JIS</strong>；</li><li><strong>一行一句</strong>：除特殊行外，每一行都是一条语句；</li><li>缩进（行首空格）不影响运行，但强烈建议使用，详见 <a href="./../guide/MCS.html">MCS 代码风格</a>。</li></ul><h2 id="行的种类" tabindex="-1">行的种类 <a class="header-anchor" href="#行的种类" aria-label="Permalink to “行的种类”">​</a></h2><table tabindex="0"><thead><tr><th>行的开头</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>@</code></td><td>函数定义</td><td>定义一个函数</td></tr><tr><td><code>#</code></td><td>预处理指令</td><td>属性、变量定义、宏等</td></tr><tr><td><code>$</code></td><td>标签</td><td>供 <code>GOTO</code> 跳转的目标</td></tr><tr><td><code>[</code> … <code>]</code></td><td>特殊区块</td><td>如 <code>[SKIPSTART]</code>、<code>[IF XXX]</code></td></tr><tr><td><code>;</code></td><td>注释</td><td>被忽略（<code>;!;</code>、<code>;#;</code> 例外）</td></tr><tr><td>其他</td><td>普通语句</td><td>赋值、命令调用等</td></tr></tbody></table><h2 id="函数定义" tabindex="-1">函数定义 <a class="header-anchor" href="#函数定义" aria-label="Permalink to “函数定义”">​</a></h2><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">函数名</span></span>
<span class="line"><span style="color:#6A9955;">  ; 函数体</span></span>
<span class="line"><span style="color:#C586C0;">  RETURN</span></span></code></pre></div><p>带参数的函数：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">函数名</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">ARG</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">ARGS</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span></span>
<span class="line"><span style="color:#6A9955;">  ; 数值参数在 ARG，字符串参数在 ARGS</span></span>
<span class="line"><span style="color:#C586C0;">  RETURN</span></span></code></pre></div><ul><li>函数从 <code>@</code> 行开始，到下一个 <code>@</code> 行或文件末尾结束；</li><li>一个文件可以定义多个函数；</li><li>事件函数（如 <code>@EVENTFIRST</code>）由引擎在特定时机调用，详见<a href="./ERB_Internal_Process.html">内置流程</a>。</li></ul><h2 id="预处理指令" tabindex="-1">预处理指令 <a class="header-anchor" href="#预处理指令" aria-label="Permalink to “预处理指令”">​</a></h2><p>以 <code>#</code> 开头的行，分为<strong>属性</strong>和<strong>定义</strong>两类：</p><ul><li><strong>属性</strong>：描述函数的性质，如 <code>#FUNCTION</code>、<code>#FUNCTIONS</code>、<code>#PRI</code>、<code>#LATER</code>、<code>#SINGLE</code>、<code>#ONLY</code>；</li><li><strong>定义</strong>：定义变量或宏，如 <code>#DIM</code>、<code>#DIMS</code>、<code>#DEFINE</code>、<code>#LOCALSIZE</code>。</li></ul><p>它们必须紧跟在函数定义之下。详见<a href="./../translation/Function_and_Preprocessor.html">函数与预处理指令</a>。</p><h2 id="标签与跳转" tabindex="-1">标签与跳转 <a class="header-anchor" href="#标签与跳转" aria-label="Permalink to “标签与跳转”">​</a></h2><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">$标签名</span></span>
<span class="line"><span style="color:#C586C0;">GOTO</span><span style="color:#9CDCFE;"> 标签名</span></span></code></pre></div><p><code>GOTO</code> 只能跳到标签（<code>$</code>）或函数（<code>@</code>），不能跳到语句中间。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to “注释”">​</a></h2><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#6A9955;">; 整行注释</span></span>
<span class="line"><span style="color:#9CDCFE;">A</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 10</span><span style="color:#6A9955;">  ; 行末注释</span></span></code></pre></div><p>两个特殊注释行用于控制引擎行为：</p><ul><li><code>;!;</code>：这一行在 Emuera 中有效，在 Eramaker 中被当作注释；</li><li><code>;#;</code>：这一行只在调试模式下执行。</li></ul><h2 id="行连接" tabindex="-1">行连接 <a class="header-anchor" href="#行连接" aria-label="Permalink to “行连接”">​</a></h2><p>当一个表达式太长时，可以用 <code>{</code> <code>}</code> 把它拆成多行：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">{</span></span>
<span class="line"><span style="color:#D4D4D4;">  #</span><span style="color:#9CDCFE;">DIM</span><span style="color:#9CDCFE;"> HOGE</span><span style="color:#D4D4D4;"> =</span></span>
<span class="line"><span style="color:#B5CEA8;">    1</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">2</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">3</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">4</span></span>
<span class="line"><span style="color:#569CD6;">}</span></span></code></pre></div><p><code>{</code> 与 <code>}</code> 必须单独成行，且换行处会补上一个半角空格。详见<a href="./../translation/General.html">常规</a>。</p><h2 id="文件的读取顺序" tabindex="-1">文件的读取顺序 <a class="header-anchor" href="#文件的读取顺序" aria-label="Permalink to “文件的读取顺序”">​</a></h2><p>Emuera 会读取 <code>ERB/</code> 下的所有文件。默认顺序取决于文件系统，可能影响同名函数、相性等的结果。如果顺序很重要，可以在配置中启用<code>読み込み順をファイル名順にソートする</code>。</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to “相关链接”">​</a></h2><ul><li><a href="./../translation/Function_and_Preprocessor.html">函数与预处理指令</a></li><li><a href="./../translation/Header_File.html">头文件（ERH）</a></li><li><a href="./../translation/General.html">常规</a></li><li><a href="./ERB_Variables.html">ERB 的变量</a></li><li><a href="./ERB_Statements.html">ERB 的语句</a></li></ul>`,30)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};